import{_ as r,C as i,o as s,c as l,aj as o,G as a,j as n}from"./chunks/framework.BwH0p-pt.js";const f=JSON.parse('{"title":"Simple Product","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/products/simple.md","filePath":"2.1/products/simple.md","lastUpdated":1785836850000}'),d={name:"2.1/products/simple.md"};function c(h,t,u,p,g,m){const e=i("ImagePopup");return s(),l("div",null,[t[0]||(t[0]=o('<h1 id="simple-product" tabindex="-1">Simple Product <a class="header-anchor" href="#simple-product" aria-label="Permalink to &quot;Simple Product&quot;">​</a></h1><p>A <strong>Simple Product</strong> is a single, standalone SKU — one physical item with one set of attributes and no variations. It&#39;s the most common product type in UnoPim and the right choice whenever a product <em>doesn&#39;t</em> need size, colour, or other variants.</p><h2 id="what-is-a-simple-product" tabindex="-1">What is a Simple Product? <a class="header-anchor" href="#what-is-a-simple-product" aria-label="Permalink to &quot;What is a Simple Product?&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Simple Product</th></tr></thead><tbody><tr><td><strong>Structure</strong></td><td>One SKU, one set of attribute values, one row in the product grid.</td></tr><tr><td><strong>When to use it</strong></td><td>The item has no variants, or each variant should be managed as its own separate record.</td></tr><tr><td><strong>Typical examples</strong></td><td>A book, a single paint colour, a specific box of screws, a ring-bound notebook.</td></tr><tr><td><strong>Compare with</strong></td><td><a href="./configurable.html">Configurable Product</a> — use that when one catalog entry needs to group multiple size/colour/material variants under a single parent.</td></tr></tbody></table><h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2><p>A Simple Product is created in two phases:</p><ol><li><strong>Create</strong> — you set the product type to <code>Simple</code>, pick an attribute family, and give it a SKU. That creates a minimal record.</li><li><strong>Edit</strong> — UnoPim redirects you to the product edit page, where you fill in the attributes defined by the family (name, description, price, categories, images, associations, …) and save.</li></ol><p>Because attribute availability is driven by the <strong>attribute family</strong>, a Simple Product in the <code>default</code> family has a different set of editable fields than one in, say, a <code>books</code> family. Managing the shape of a Simple Product means managing its family — see <a href="./../attribute/attribute-family.html">Attribute Family</a>.</p><h2 id="how-to-create-a-simple-product" tabindex="-1">How to Create a Simple Product <a class="header-anchor" href="#how-to-create-a-simple-product" aria-label="Permalink to &quot;How to Create a Simple Product&quot;">​</a></h2><h3 id="step-1-—-start-creation" tabindex="-1">Step 1 — Start creation <a class="header-anchor" href="#step-1-—-start-creation" aria-label="Permalink to &quot;Step 1 — Start creation&quot;">​</a></h3><ol><li>Click <strong>Catalog → Products</strong>.</li><li>In the top-right corner, click <strong>Create Product</strong>. A dialog titled <strong>&quot;Create New Product&quot;</strong> opens.</li><li>Fill in the three fields: <ul><li><strong>Type</strong> — <code>Simple</code>.</li><li><strong>Family</strong> — the attribute family that controls which fields will appear on the edit page.</li><li><strong>SKU</strong> — a unique identifier for the product.</li></ul></li><li>Click <strong>Save Product</strong>.</li></ol>',11)),a(e,{src:"/assets/2.1/images/simple-product/simple.png",alt:"Create Simple Product modal"}),t[1]||(t[1]=n("p",null,"UnoPim closes the dialog and redirects you to the edit page, where every remaining field can be filled in.",-1)),a(e,{src:"/assets/2.1/images/simple-product/editProduct.png",alt:"Edit Simple Product"}),t[2]||(t[2]=o('<h3 id="step-2-—-fill-in-the-product-details" tabindex="-1">Step 2 — Fill in the product details <a class="header-anchor" href="#step-2-—-fill-in-the-product-details" aria-label="Permalink to &quot;Step 2 — Fill in the product details&quot;">​</a></h3><p>The edit page groups attributes by <strong>Attribute Group</strong> (General, Short Description, Description, Price, Technical, Categories, Associations, …). Exactly which groups appear depends on the family you chose at creation.</p><p>The <code>default</code> family requires at minimum:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>SKU</strong></td><td>Unique product identifier. Cannot be duplicated.</td></tr><tr><td><strong>Name</strong></td><td>Display name shown to customers.</td></tr><tr><td><strong>URL Key</strong></td><td>URL-safe slug for storefront links.</td></tr></tbody></table><p>Additional built-in sections for the <code>default</code> family:</p><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Short Description</strong></td><td>One- or two-line summary. Appears on listing cards and SEO previews.</td></tr><tr><td><strong>Description</strong></td><td>Full product copy — can use the WYSIWYG editor.</td></tr><tr><td><strong>Price</strong></td><td>Selling price plus cost price per currency.</td></tr><tr><td><strong>Technical</strong></td><td>Status toggle — enables/disables the product.</td></tr><tr><td><strong>Categories</strong></td><td>Assign the product to one or more categories (including a root category).</td></tr><tr><td><strong>Associations</strong></td><td>Related / Up-sell / Cross-sell product links (see below).</td></tr></tbody></table><p>Each section appears as its own card on the edit page. The <strong>Short Description</strong> and <strong>Description</strong> cards include a WYSIWYG editor for rich text. The <strong>Price</strong> card shows one row per configured currency. The <strong>Technical</strong> card holds the green <strong>Status</strong> toggle — leave it <em>Enabled</em> for the product to be considered active. The <strong>Categories</strong> card opens a tree picker; tick every node the product belongs to. All cards share the same <em>Save Product</em> button in the top-right of the page.</p><h3 id="step-3-—-add-associations" tabindex="-1">Step 3 — Add associations <a class="header-anchor" href="#step-3-—-add-associations" aria-label="Permalink to &quot;Step 3 — Add associations&quot;">​</a></h3><p>At the bottom of the edit page you can link this product to others. All three sections work the same way: click <strong>Add</strong>, search by SKU, then click <strong>Add Selected Product</strong>.</p><table tabindex="0"><thead><tr><th>Association</th><th>When to use it</th></tr></thead><tbody><tr><td><strong>Related Products</strong></td><td>Similar alternatives — helps customers discover substitutes they might also like.</td></tr><tr><td><strong>Up-Sell Products</strong></td><td>Higher-end versions — a better TV, a faster laptop, a more durable tablet.</td></tr><tr><td><strong>Cross-Sell Products</strong></td><td>Complementary items — protective case + laptop, adapter + phone.</td></tr></tbody></table><p>Each of the three association cards has the same layout: an <strong>Add</strong> button opens a search-by-SKU picker, ticked products appear as a list underneath with a ✕ button to remove them, and there&#39;s no limit on how many you can add.</p><h3 id="step-4-—-save" tabindex="-1">Step 4 — Save <a class="header-anchor" href="#step-4-—-save" aria-label="Permalink to &quot;Step 4 — Save&quot;">​</a></h3><p>Click <strong>Save Product</strong> in the top-right of the edit page. You&#39;re redirected back to the <strong>Products Data Grid</strong>, where the new product appears as a row with its SKU, image thumbnail, name, attribute family, status chip, type (<em>Simple</em>), and completeness percentage.</p>',13)),a(e,{src:"/assets/2.1/images/simple-product/datagrid.png",alt:"Products Datagrid"}),t[3]||(t[3]=o('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Attributes that support values per channel show a <strong>channel badge</strong>. Attributes that support values per locale show a <strong>locale badge</strong>. Attributes that support both show both badges — these are the fields you&#39;ll revisit when you switch channels or locales on the edit page.</p></div><h2 id="working-with-a-simple-product-after-creation" tabindex="-1">Working with a Simple Product after creation <a class="header-anchor" href="#working-with-a-simple-product-after-creation" aria-label="Permalink to &quot;Working with a Simple Product after creation&quot;">​</a></h2><p>Once created, a Simple Product supports the full set of UnoPim product features. The rest of this page groups them by what you&#39;re trying to do.</p><h3 id="translate-values-across-locales" tabindex="-1">Translate values across locales <a class="header-anchor" href="#translate-values-across-locales" aria-label="Permalink to &quot;Translate values across locales&quot;">​</a></h3><p>UnoPim supports <strong>Product Values Translation</strong> — per-locale values for any attribute flagged as locale-specific.</p>',5)),a(e,{src:"/assets/2.1/images/simple-product/product-edit-locale.png",alt:"Product Edit with Locale Switcher"}),t[4]||(t[4]=o('<h4 id="manual-translation" tabindex="-1">Manual translation <a class="header-anchor" href="#manual-translation" aria-label="Permalink to &quot;Manual translation&quot;">​</a></h4><ol><li>Open the product in <strong>Catalog → Products</strong>.</li><li>At the top of the edit page, use the two switchers: <ul><li><strong>Channel Switcher</strong> (e.g., <em>Default</em>) — picks which channel&#39;s values you&#39;re editing.</li><li><strong>Locale Switcher</strong> (e.g., <em>English (United States)</em>) — picks the locale.</li></ul></li><li>Switch to the target locale. The form reloads with that locale&#39;s values. Locale-specific fields show a locale badge (e.g., <code>EN_US</code>).</li><li>Enter the translated values (Name, Description, URL Key, …).</li><li>Click <strong>Save Product</strong>.</li><li>Repeat per locale.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A <strong>DEFAULT</strong> badge means channel-specific. A locale badge (e.g., <code>EN_US</code>) means locale-specific. Both badges together means the attribute supports values per channel <strong>and</strong> per locale.</p></div><h4 id="auto-translation-with-magic-ai" tabindex="-1">Auto-translation with Magic AI <a class="header-anchor" href="#auto-translation-with-magic-ai" aria-label="Permalink to &quot;Auto-translation with Magic AI&quot;">​</a></h4><p>Enable <strong>Magic AI → Settings → Translation</strong> and every product save auto-translates locale-specific fields into the target locales:</p><ol><li>Toggle <strong>Enabled</strong> on.</li><li>Set the <strong>Source Channel</strong> and <strong>Source Locale</strong> (the language you write in).</li><li>Set the <strong>Target Channel</strong> and <strong>Target Locales</strong>.</li><li>Pick a <strong>Translation Model</strong> — you can use a cheaper/faster provider for this.</li><li>Optionally toggle <strong>Replace Existing Value</strong> to overwrite existing translations on re-run.</li></ol><p>See <a href="./../magic-ai/settings.html">Magic AI — Settings</a> for the full field reference.</p><h3 id="check-completeness" tabindex="-1">Check completeness <a class="header-anchor" href="#check-completeness" aria-label="Permalink to &quot;Check completeness&quot;">​</a></h3><p>UnoPim computes a <strong>Product Completeness</strong> score per product, per channel, per locale:</p><ul><li>Score is displayed as a percentage (e.g., 89%).</li><li>Low-completeness products show <em>&quot;Low completeness, add details to improve&quot;</em>.</li><li>Nearly-complete products show <em>&quot;Almost complete, just a few details left&quot;</em>.</li><li>The Dashboard aggregates completeness per channel in the <strong>Completeness</strong> widget.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Pair completeness with <strong>Magic AI Auto-Enrichment</strong> (Magic AI → Settings → Agentic PIM) to automatically fill in missing fields and bump the score.</p></div><h3 id="review-change-history" tabindex="-1">Review change history <a class="header-anchor" href="#review-change-history" aria-label="Permalink to &quot;Review change history&quot;">​</a></h3><p>Click the <strong>History</strong> tab on the product edit page to see every change. Each entry records:</p><ul><li>Date/time of the change.</li><li>The user who made it.</li><li>Exact fields that were modified, with before/after values.</li></ul><p>Click the <strong>eye icon</strong> on any entry to open a detail view that shows the before and after values side by side. UnoPim tracks history for <strong>products, categories, attributes, attribute families, and channels</strong> with the same UI.</p><h3 id="duplicate-a-product" tabindex="-1">Duplicate a product <a class="header-anchor" href="#duplicate-a-product" aria-label="Permalink to &quot;Duplicate a product&quot;">​</a></h3><p>To create a new product seeded from an existing one:</p><ol><li>In <strong>Catalog → Products</strong>, find the row to copy.</li><li>Click the <strong>Copy icon</strong> (clipboard) in the Actions column.</li><li>UnoPim creates a duplicate with a new SKU.</li><li>Edit the copy to customise it.</li></ol><h2 id="working-with-the-products-listing" tabindex="-1">Working with the Products listing <a class="header-anchor" href="#working-with-the-products-listing" aria-label="Permalink to &quot;Working with the Products listing&quot;">​</a></h2><p>The listing at <strong>Catalog → Products</strong> is where you find, filter, bulk-edit, and export products.</p><h3 id="manage-columns" tabindex="-1">Manage columns <a class="header-anchor" href="#manage-columns" aria-label="Permalink to &quot;Manage columns&quot;">​</a></h3><p>Click the <strong>Columns</strong> button to open the <strong>Manage columns</strong> modal.</p>',22)),a(e,{src:"/assets/2.1/images/simple-product/columns-selector.png",alt:"Columns Selector"}),t[5]||(t[5]=o('<table tabindex="0"><thead><tr><th>Panel</th><th>Contents</th></tr></thead><tbody><tr><td><strong>Available Columns</strong> (left)</td><td>Every attribute that can be shown as a column — ID, Parent, Created/Updated At, URL Key, Tax Category, Short Description, Description, Price, Cost, Meta Title, Meta Keywords, Meta Description, plus every custom attribute. Search + pagination.</td></tr><tr><td><strong>Selected Columns</strong> (right)</td><td>Currently visible columns. Default: SKU, Image, Name, Attribute Family, Status, Type, Complete.</td></tr></tbody></table><p>To customise:</p><ol><li>Drag from Available to Selected to add a column.</li><li>Drag within Selected to reorder.</li><li>Drag out of Selected (or click remove) to hide.</li><li>Click <strong>Apply</strong>.</li></ol><h3 id="filter-products" tabindex="-1">Filter products <a class="header-anchor" href="#filter-products" aria-label="Permalink to &quot;Filter products&quot;">​</a></h3><p>Click <strong>Filter</strong> above the datagrid to slide open the <strong>Apply Filters</strong> drawer from the right side of the screen. The drawer carries a fixed set of built-in filter fields plus an <strong>Add Filter</strong> button for custom attributes.</p><p><strong>Built-in filters</strong> (always shown):</p><ul><li><strong>SKU</strong> — text match.</li><li><strong>Name</strong> — text match.</li><li><strong>Attribute Family</strong> — dropdown of all configured families.</li><li><strong>Status</strong> — Enabled / Disabled dropdown.</li><li><strong>Type</strong> — Simple / Configurable dropdown.</li></ul><p><strong>Add Filter (custom attributes)</strong></p><p>Click <strong>Add Filter</strong> at the bottom of the drawer to append a filter for any attribute that has <strong>Is Filterable</strong> ticked on its Configuration card (see <a href="./../attribute/product-attribute.html#add-attributes">Product Attribute → Configuration</a>). This is how you filter the listing by <code>color</code>, <code>size</code>, <code>brand</code>, or any other attribute relevant to your catalog:</p><ol><li>In the drawer, click <strong>Add Filter</strong>.</li><li>Pick an attribute from the dropdown — only attributes with <strong>Is Filterable = on</strong> are listed.</li><li>Enter or select the value(s) to filter on. Input shape depends on the attribute&#39;s data type (text input, select dropdown, date range, checkbox, etc.).</li><li>Repeat <strong>Add Filter</strong> to stack more filters — they combine with AND logic.</li></ol><p>Click <strong>Save</strong> at the bottom of the drawer to apply the filter set. The datagrid reloads showing only the matching rows. To clear, open the drawer again and remove individual filter chips, or reload the page to reset.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If an attribute you want to filter by isn&#39;t in the Add Filter dropdown, head to <strong>Catalog → Attributes</strong>, edit the attribute, tick <strong>Is Filterable</strong> in the Configuration card, and save. It appears in the dropdown immediately.</p></div><h3 id="bulk-edit" tabindex="-1">Bulk edit <a class="header-anchor" href="#bulk-edit" aria-label="Permalink to &quot;Bulk edit&quot;">​</a></h3><p>UnoPim supports <strong>Bulk Edit</strong> on any attribute shared by the selected products:</p><ol><li>Go to <strong>Catalog → Products</strong>.</li><li>Tick the rows you want to edit.</li><li>Open the <strong>Bulk Actions</strong> dropdown.</li><li>Select <strong>Edit</strong> and choose the attribute.</li><li>Enter the new value and apply.</li></ol><h4 id="bulk-enable-disable" tabindex="-1">Bulk Enable / Disable <a class="header-anchor" href="#bulk-enable-disable" aria-label="Permalink to &quot;Bulk Enable / Disable&quot;">​</a></h4><ol><li>Select multiple products.</li><li>In the bulk action bar, choose <strong>Enable</strong> or <strong>Disable</strong>.</li></ol><h4 id="bulk-delete" tabindex="-1">Bulk Delete <a class="header-anchor" href="#bulk-delete" aria-label="Permalink to &quot;Bulk Delete&quot;">​</a></h4><ol><li>Select the products.</li><li>Click <strong>Delete</strong>.</li><li>Confirm — the deletion is permanent.</li></ol><h3 id="quick-export" tabindex="-1">Quick Export <a class="header-anchor" href="#quick-export" aria-label="Permalink to &quot;Quick Export&quot;">​</a></h3><p>Export selected (or all) products directly from the listing:</p><ol><li>Select the products.</li><li>Click <strong>Quick Export</strong> in the top-right, next to <strong>Create Product</strong>.</li><li>Choose <strong>CSV</strong>, <strong>XLS</strong>, or <strong>XLSX</strong> from the format picker.</li><li>UnoPim generates the file in the background and downloads it to your browser once processing finishes. You can watch the job progress on the <strong>Job Tracker</strong> page while you wait.</li></ol><p>For scheduled or filtered exports, use the full <strong><a href="./../data-transfer/export.html">Export</a></strong> workflow in Data Transfer.</p><h2 id="related-reading" tabindex="-1">Related reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related reading&quot;">​</a></h2><ul><li><strong><a href="./configurable.html">Configurable Product</a></strong> — when to use variants instead of a single Simple SKU.</li><li><strong><a href="./../attribute/attribute-family.html">Attribute Family</a></strong> — controls which fields appear on a Simple Product.</li><li><strong><a href="./../magic-ai/settings.html">Magic AI — Settings</a></strong> — configure auto-translation and auto-enrichment for products.</li><li><strong><a href="./../ai-agent/ai-agent-chat.html">AI Agent Chat</a></strong> — create, update, and bulk-edit Simple Products via natural language.</li></ul>',25))])}const w=r(d,[["render",c]]);export{f as __pageData,w as default};
